/* @lc app=leetcode id=2213 lang=kotlin */ class Solution { fun mg(a: IntArray, b: IntArray): IntArray = if (a[0] == 0) b else if (b[0] == 0) a else (a[5] == b[4]).let { eq -> intArrayOf(a[0] + b[0], if (eq && a[1] == a[0]) a[0] + b[1] else a[1], if (eq && b[2] == b[0]) b[0] + a[2] else b[2], maxOf(a[3], b[3], if (eq) a[2] + b[1] else 0), a[4], b[5]) } fun lf(c: Char) = intArrayOf(1, 1, 1, 1, c.code, c.code) fun longestRepeating(s: String, queryCharacters: String, queryIndices: IntArray): IntArray = generateSequence(1) { it * 2 }.first { it >= s.length }.let { sz -> Array(2 * sz) { intArrayOf(0, 0, 0, 0, -1, -1) }.also { t -> s.indices.forEach { i -> t[sz + i] = lf(s[i]) } }.also { t -> (sz - 1 downTo 1).forEach { i -> t[i] = mg(t[2 * i], t[2 * i + 1]) } }.let { t -> queryIndices.indices.map { q -> generateSequence(sz + queryIndices[q]) { it / 2 }.takeWhile { it >= 1 }.fold(true) { first, i -> (if (first) lf(queryCharacters[q]).also { t[i] = it } else mg(t[2 * i], t[2 * i + 1]).also { t[i] = it }).let { false } }.let { t[1][3] } }.toIntArray() } } }